package xiaozhi.modules.diagnostics;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.mock.web.MockHttpServletRequest;
import xiaozhi.modules.airuntime.AiRuntimeControl;
import xiaozhi.modules.security.user.SecurityUser;
import xiaozhi.modules.externalidentity.ExternalIdentityService;
class AiOperationsDiagnosticsTest {
    JdbcTemplate db=mock(JdbcTemplate.class);MockEnvironment env=new MockEnvironment();
    Map<String,Object> metrics(long expired,long queued,long provider){var row=new HashMap<String,Object>();for(String key:List.of("active","queued","expired_leases","queue_overdue","completed","failed","canceled","provider_failures_15m"))row.put(key,0L);row.put("active",2L);row.put("expired_leases",expired);row.put("queue_overdue",queued);row.put("provider_failures_15m",provider);row.put("last_success",Timestamp.from(Instant.parse("2026-11-02T00:00:00Z")));return row;}
    @Test void disabledModulesNeverReadTheirTablesAndHaveNoFakeZeroCounters(){when(db.queryForObject("SELECT 1",Integer.class)).thenReturn(1);var result=new AiOperationsDiagnosticsService(db,env).snapshot(1);assertEquals("limited",result.get("state"));var flows=(Map<?,?>)result.get("flows");for(Object flow:flows.values()){var m=(Map<?,?>)flow;assertEquals("disabled",m.get("state"));assertFalse(m.containsKey("active"));}verify(db).queryForObject("SELECT 1",Integer.class);verifyNoMoreInteractions(db);}
    @Test void oneFailedModuleBecomesUnknownWithoutClaimingZeroHealth(){when(db.queryForObject("SELECT 1",Integer.class)).thenReturn(1);when(db.queryForMap(anyString())).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private password"));env.withProperty("features.conversation-enabled","true").withProperty("features.ai-text-enabled","true");var result=new AiOperationsDiagnosticsService(db,env).snapshot(1);var ai=(Map<?,?>)((Map<?,?>)result.get("flows")).get("ai");assertEquals("unknown",ai.get("state"));assertFalse(ai.containsKey("active"));assertEquals("degraded",result.get("state"));assertFalse(result.toString().contains("password"));}
    @Test void currentStallsAreNotHiddenByCreationWindowAndProviderThresholdIsThree(){when(db.queryForObject("SELECT 1",Integer.class)).thenReturn(1);when(db.queryForMap(anyString())).thenReturn(metrics(2,1,3));when(db.queryForList(anyString())).thenReturn(List.of(Map.of("safe_group","authorization","total",9L)));env.withProperty("features.conversation-enabled","true").withProperty("features.ai-text-enabled","true");var result=new AiOperationsDiagnosticsService(db,env).snapshot(1);var alerts=(List<?>)result.get("alerts");assertEquals(3,alerts.size());assertTrue(alerts.toString().contains("current_active_state"));assertTrue(alerts.toString().contains("PROVIDER_FAILURE_CONCENTRATION"));when(db.queryForMap(anyString())).thenReturn(metrics(0,0,2));assertEquals(List.of(),new AiOperationsDiagnosticsService(db,env).snapshot(1).get("alerts"));}
    @Test void emptyRealtimeConnectionIsNotObservedAsModelSuccess(){when(db.queryForObject("SELECT 1",Integer.class)).thenReturn(1);when(db.queryForMap(anyString())).thenReturn(metrics(0,0,0));when(db.queryForList(anyString())).thenReturn(List.of());env.withProperty("features.conversation-enabled","true").withProperty("features.realtime-ai-enabled","true");var result=new AiOperationsDiagnosticsService(db,env).snapshot(1);var rt=(Map<?,?>)((Map<?,?>)result.get("flows")).get("realtime");assertNull(rt.get("observed_last_success_at"));verify(db).queryForObject(contains("kind='assistant' AND status='completed'"),eq(Timestamp.class));}
    @Test void actualMapperKeepsSnakeCaseStringCountsAndExplicitUnknownUnits()throws Exception {when(db.queryForObject("SELECT 1",Integer.class)).thenReturn(1);when(db.queryForMap(anyString())).thenReturn(metrics(0,0,0));when(db.queryForList(anyString())).thenReturn(List.of());env.withProperty("features.conversation-enabled","true").withProperty("features.ai-text-enabled","true").withProperty("features.realtime-ai-enabled","true").withProperty("features.realtime-materials-enabled","true").withProperty("features.answer-speech-enabled","true");var runtime=mock(AiRuntimeControl.class);when(runtime.enabled()).thenReturn(true);when(runtime.snapshot(1L)).thenReturn(new AiRuntimeControl.Snapshot(true,3600,new AiRuntimeControl.Limits(3,32,60,1000),new AiRuntimeControl.Scope(0,0,3,60),new AiRuntimeControl.Scope(0,0,32,1000),new AiRuntimeControl.Usage(null,0,0,null,0,0),false,"concurrency_and_request_admission_not_total_cost"));var service=new AiOperationsDiagnosticsService(db,env);service.setRuntime(runtime);var mapper=new xiaozhi.modules.security.config.WebMvcConfig().jackson2HttpMessageConverter().getObjectMapper();var result=mapper.readTree(mapper.writeValueAsBytes(new xiaozhi.common.utils.Result<>().ok(service.snapshot(1))));var ai=result.path("data").path("flows").path("ai");assertEquals("2",ai.path("active").asText());assertTrue(ai.path("active").isTextual());assertTrue(ai.path("error_groups_60m").isArray());assertEquals("2026-11-02T00:00:00Z",ai.path("observed_last_success_at").asText());var snapshot=result.path("data").path("runtime_control").path("snapshot");assertTrue(snapshot.path("usage").path("known_tokens").isNull());assertTrue(snapshot.path("usage").path("known_speech_characters").isNull());assertTrue(snapshot.has("service_limited"));assertFalse(snapshot.has("serviceLimited"));assertTrue(result.path("data").path("window_seconds").path("alerts").isInt());}
    @Test void runtimeFailureIsUnknownWhileTheModuleSummariesRemainAvailable(){when(db.queryForObject("SELECT 1",Integer.class)).thenReturn(1);var runtime=mock(AiRuntimeControl.class);when(runtime.enabled()).thenReturn(true);when(runtime.snapshot(any())).thenThrow(new IllegalStateException("secret"));var service=new AiOperationsDiagnosticsService(db,env);service.setRuntime(runtime);var result=service.snapshot(1);assertEquals(Map.of("state","unknown"),result.get("runtime_control"));assertEquals("degraded",result.get("state"));assertFalse(result.toString().contains("secret"));verify(runtime,never()).snapshot(any());}
    @Test void controllerEnforcesAnonymousExternalOrdinaryAndNoQueryWithoutLeaks(){var access=mock(ServerDiagnosticsService.class);var service=mock(AiOperationsDiagnosticsService.class);var controller=new AiOperationsDiagnosticsController(access,service);var request=new MockHttpServletRequest();try(var security=mockStatic(SecurityUser.class)){assertEquals(401,controller.get(request).getStatusCode().value());security.when(SecurityUser::getUserId).thenReturn(9L);assertEquals(403,controller.get(request).getStatusCode().value());when(access.administrator(9)).thenReturn(true);request.setQueryString("owner=123");assertEquals(400,controller.get(request).getStatusCode().value());request.setQueryString(null);request.setAttribute(ExternalIdentityService.ATTRIBUTE,new Object());assertEquals(403,controller.get(request).getStatusCode().value());request.removeAttribute(ExternalIdentityService.ATTRIBUTE);request.addHeader("Authorization","Bearer xext_secret");assertEquals(403,controller.get(request).getStatusCode().value());verifyNoInteractions(service);}}
    @Test void wholeDatabaseFailureUses503PrivateHeadersAndFixedBody(){var access=mock(ServerDiagnosticsService.class);var service=mock(AiOperationsDiagnosticsService.class);var controller=new AiOperationsDiagnosticsController(access,service);try(var security=mockStatic(SecurityUser.class)){security.when(SecurityUser::getUserId).thenReturn(1L);when(access.administrator(1)).thenReturn(true);when(service.snapshot(1)).thenThrow(new IllegalStateException("jdbc://host/private_key"));var response=controller.get(new MockHttpServletRequest());assertEquals(503,response.getStatusCode().value());assertEquals("private, no-store",response.getHeaders().getCacheControl());assertEquals("nosniff",response.getHeaders().getFirst("X-Content-Type-Options"));assertFalse(response.toString().contains("private_key"));assertEquals("AI_DIAGNOSTICS_DATABASE_UNKNOWN",response.getBody().getMsg());}}
}
